mapper.select:
SELECT r.recipe_id, r.recipe_category_id, rc.category_name, r.title, r.thumbnail_url, r.cooking_time, r.difficulty, r.like_count, r.cooked_count, COALESCE(p.nickname, '(알 수 없음)') AS author_nickname, p.user_tag AS author_tag FROM public.recipe r JOIN public.recipe_category rc ON r.recipe_category_id = rc.recipe_category_id LEFT JOIN public.profiles p ON r.user_id = p.id
AND r.user_id = #{userId}
AND EXISTS ( SELECT 1 FROM public.scrap s WHERE s.recipe_id = r.recipe_id AND s.user_id = #{userId} )
AND r.recipe_category_id = #{recipeCategoryId}
AND ( r.title ILIKE CONCAT('%', #{query}, '%') OR EXISTS ( SELECT 1 FROM public.recipe_ingredient ri WHERE ri.recipe_id = r.recipe_id AND ri.name ILIKE CONCAT('%', #{query}, '%') ) )
ORDER BY r.like_count DESC, r.created_at DESC
ORDER BY r.cooked_count DESC, r.created_at DESC
ORDER BY r.created_at DESC, r.recipe_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM public.recipe r


        AND r.user_id = #{userId}


        AND EXISTS (
            SELECT 1 FROM public.scrap s
            WHERE s.recipe_id = r.recipe_id
              AND s.user_id = #{userId}
        )


        AND r.recipe_category_id = #{recipeCategoryId}


        AND (
            r.title ILIKE CONCAT('%', #{query}, '%')
            OR EXISTS (
                SELECT 1 FROM public.recipe_ingredient ri
                WHERE ri.recipe_id = r.recipe_id
                  AND ri.name ILIKE CONCAT('%', #{query}, '%')
            )
        )

mapper.update:
UPDATE public.recipe
SET like_count = like_count + 1
WHERE recipe_id = #{recipeId}

UPDATE public.recipe
SET like_count = GREATEST(0, like_count - 1)
WHERE recipe_id = #{recipeId}

UPDATE public.recipe
SET cooked_count = cooked_count + 1
WHERE recipe_id = #{recipeId}

mapper.select:
SELECT r.recipe_id, r.user_id, r.recipe_category_id, r.title, r.description, r.servings, r.cooking_time, r.difficulty, r.thumbnail_url, r.like_count, r.cooked_count, r.created_at, r.updated_at FROM public.recipe r
AND r.recipe_category_id = #{recipeCategoryId}
ORDER BY r.created_at DESC
